<template><div class="strategy-thumbnail"><svg v-if="path" viewBox="0 0 240 86" preserveAspectRatio="none" role="img" aria-label="真实历史走势缩略图"><path :d="area" class="thumb-area"/><polyline :points="path" class="thumb-line"/><line v-if="signal" :x1="signalX" :x2="signalX" y1="8" y2="78" class="thumb-signal"/></svg><span v-else>{{ emptyText }}</span></div></template>
<script setup>import{computed}from'vue';const props=defineProps({points:{type:Array,default:()=>[]},signal:{type:Object,default:null},emptyText:{type:String,default:'等待真实样本'}});const plotted=computed(()=>{const v=props.points.map(Number).filter(Number.isFinite);if(v.length<2)return[];const min=Math.min(...v),max=Math.max(...v),span=max-min||1;return v.map((n,i)=>({x:4+i/Math.max(v.length-1,1)*232,y:78-(n-min)/span*68}))});const path=computed(()=>plotted.value.map(p=>`${p.x},${p.y}`).join(' '));const area=computed(()=>path.value?`M 4 82 L ${path.value.replaceAll(' ',', L ')} L 236 82 Z`:"");const signalX=computed(()=>Math.max(4,Math.min(236,4+((props.signal?.chart_before?.length||1)-1)/Math.max(props.points.length-1,1)*232)));
</script><style scoped>.strategy-thumbnail{height:86px;display:grid;place-items:center;background:#0b1526;border:1px solid #203454;border-radius:8px;color:#71839e;font-size:12px;overflow:hidden}.strategy-thumbnail svg{width:100%;height:100%}.thumb-line{fill:none;stroke:#4aa3ff;stroke-width:2}.thumb-area{fill:#1b5f9e;opacity:.18}.thumb-signal{stroke:#f5b94c;stroke-dasharray:3 3}</style>
